"""Render docs/model_card.md from the champion's report, so the documented numbers are the measured ones."""

from pathlib import Path

from churn import registry


def _ci(m):
    return f"{m['value']:.3f} [{m['ci'][0]:.3f}, {m['ci'][1]:.3f}]"


def _money(v):
    return f"−${-v:,.0f}" if v < 0 else f"${v:,.0f}"


def model_card(r):
    sel, cal, t = r["selection"], r["calibration"], r["test"]
    chosen = sel["chosen"]
    models = t["models"]
    ref = t["reference_model"]
    lines = [
        f"# Model card: {r['version']}",
        "",
        "_Generated by `python -m churn.train --promote` from `models/{v}/report.json`. Do not edit by hand._".format(
            v=r["version"]
        ),
        "",
        "## Intended use",
        "Rank existing telecom customers for a paid retention offer, and decide per customer whether the offer is worth "
        "its cost. The output is a calibrated churn probability, an expected-value decision and the top reasons.",
        "",
        "**Not for:** pricing, credit or eligibility decisions; customers outside a consumer telecom base like the training data; "
        "estimating whether an offer *changes* behaviour (that needs uplift modelling on A/B campaign data).",
        "",
        "## Data",
        f"IBM Telco Customer Churn, {r['n_customers']:,} customers, one static snapshot (SHA-256 `{r['data_sha256'][:12]}…`). "
        "Each customer is assigned to a split by a hash of their ID, so the assignment never changes as data grows.",
        "",
        "| Split | Customers | Churn rate | Used for |",
        "|---|---|---|---|",
    ]
    uses = {
        "train": "model selection (Optuna, 5-fold CV)",
        "calibration": "calibrator choice and fit, decision threshold",
        "test": "final evaluation, touched once",
    }
    lines += [f"| {k} | {v['n']:,} | {v['churn_rate']:.1%} | {uses[k]} |" for k, v in r["splits"].items()]
    lines += [
        "",
        f"Features: {len(r['features'])} (`TotalCharges` is excluded: it is ≈ tenure × MonthlyCharges. Including it changes "
        f"CV log loss from {sel['ablation_cv_log_loss']['without_total_charges']:.4f} to {sel['ablation_cv_log_loss']['with_total_charges']:.4f}; "
        "it was dropped so explanations do not split credit between two copies of tenure).",
        "",
        "## Model selection (train split only)",
        f"Criterion: {sel['criterion']}. Log loss, not AUC, because the profit policy multiplies by the probabilities.",
        "",
        "| Candidate | CV log loss | Notes |",
        "|---|---|---|",
    ]
    for k, c in sel["candidates"].items():
        trials = sel["optuna"].get(c["family"]) if k != "xgboost_default" else None
        note = (
            f"Optuna TPE, {trials['n_trials']} trials ({trials['pruned']} pruned)" if trials else "previous hand-set parameters"
        )
        lines.append(f"| {k}{' **(chosen)**' if k == chosen else ''} | {c['cv_log_loss']:.4f} | {note} |")
    lines += [
        "",
        "## Calibration and decision threshold (calibration split only)",
        f"Calibrator chosen by 5-fold CV log loss: **{cal['method']}** "
        f"({', '.join(f'{k} {v:.4f}' for k, v in cal['cv_log_loss'].items())}). "
        f"Test ECE: {cal['ece_raw']:.3f} raw → {models[chosen]['ece']['value']:.3f} calibrated.",
        "",
        f"Decision rule: contact when expected value = P(churn) × save rate × {r['economics']['horizon']} × monthly bill − offer cost "
        f"exceeds a margin. The margin was tuned on cross-fitted calibrated probabilities: **{_money(r['threshold']['margin'])}** "
        "($0 is the Bayes-optimal margin for perfectly calibrated probabilities). "
        f"Test profit at the tuned margin: {_money(r['threshold']['test_profit_at_tuned_margin'])}; "
        f"at $0: {_money(r['threshold']['test_profit_at_zero_margin'])}.",
        "",
        "ECE intervals sit above the point estimate: resampling duplicates customers, which inflates binned calibration error, "
        "so read them as conservative.",
        "",
        "## Test performance (95% paired-bootstrap CIs, 2,000 resamples)",
        "",
        "| Model | ROC-AUC | PR-AUC | Log loss | Brier | ECE | Profit |",
        "|---|---|---|---|---|---|---|",
    ]
    for k, m in models.items():
        lines.append(
            f"| {k}{' (served)' if k == chosen else ''} | {_ci(m['roc_auc'])} | {_ci(m['pr_auc'])} | {_ci(m['log_loss'])} | "
            f"{_ci(m['brier'])} | {_ci(m['ece'])} | {_money(m['profit']['value'])} [{_money(m['profit']['ci'][0])}, {_money(m['profit']['ci'][1])}] |"
        )
    if chosen != ref:
        d = models[chosen][f"vs_{ref}"]
        lines += [
            "",
            f"**Served model minus {ref} (paired):** ROC-AUC {d['roc_auc']['diff']:+.4f} [{d['roc_auc']['ci'][0]:+.4f}, {d['roc_auc']['ci'][1]:+.4f}], "
            f"log loss {d['log_loss']['diff']:+.4f} [{d['log_loss']['ci'][0]:+.4f}, {d['log_loss']['ci'][1]:+.4f}], "
            f"profit {_money(d['profit']['diff'])} [{_money(d['profit']['ci'][0])}, {_money(d['profit']['ci'][1])}]. "
            "An interval that spans zero means the test set cannot tell the two models apart.",
        ]
    lines += [
        "",
        "## Retention policy on the test customers",
        "",
        "| Policy | Contacted | Precision | Recall | Profit [95% CI] |",
        "|---|---|---|---|---|",
    ]
    for k, p in t["policies"].items():
        lines.append(
            f"| {k} | {p['contacted']:,} | {p['precision']:.1%} | {p['recall']:.1%} | {_money(p['profit'])} [{_money(p['profit_ci'][0])}, {_money(p['profit_ci'][1])}] |"
        )
    d = t["ev_vs_p05_profit"]
    lines += [
        "",
        f"**Expected-value targeting minus the P > 0.5 rule (paired):** {_money(d['diff'])} "
        f"[{_money(d['ci'][0])}, {_money(d['ci'][1])}].",
    ]
    worst = sorted((s for s in r["subgroups"] if s["n"] >= 150), key=lambda s: -abs(s["calibration_gap"]))[:5]
    lines += [
        "",
        "## Subgroups (test, segments with n ≥ 150, largest calibration gaps first)",
        "",
        "| Segment | n | Churn rate | Mean predicted | ROC-AUC [95% CI] | Recall |",
        "|---|---|---|---|---|---|",
    ]
    for s in worst:
        auc = f"{s['roc_auc']:.3f} [{s['roc_auc_ci'][0]:.3f}, {s['roc_auc_ci'][1]:.3f}]" if s["roc_auc"] else "n/a"
        lines.append(
            f"| {s['column']} = {s['level']} | {s['n']} | {s['churn_rate']:.1%} | {s['mean_predicted']:.1%} | {auc} | "
            f"{s['recall']:.1%} |"
            if s["recall"] is not None
            else f"| {s['column']} = {s['level']} | {s['n']} | {s['churn_rate']:.1%} | {s['mean_predicted']:.1%} | {auc} | n/a |"
        )
    e = r["errors"]
    lines += [
        "",
        "## Errors",
        f"- Wasted offers (contacted, did not churn): {e['wasted_offers']['count']} customers, {_money(e['wasted_offers']['cost'])}.",
        f"- Missed churners an offer would have paid off on: {e['missed_profitable_churners']['count']}, {_money(e['missed_profitable_churners']['forgone_profit'])} forgone.",
        f"- Missed churners on plans too cheap to be worth an offer: {e['missed_unprofitable_churners']} (skipped by design).",
        "",
        "## Explanations",
        "Per-customer reasons are exact SHAP values in log-odds (TreeSHAP for XGBoost), with one-hot columns summed back to their source feature. "
        f"Features whose association exceeds {r['explain']['group_threshold']} (|Spearman|, Cramér's V or correlation ratio, average linkage) "
        "form a group. Read credit at the group level: SHAP splits credit among correlated features arbitrarily.",
        "",
        "| Group | Mean |SHAP| (log-odds) |",
        "|---|---|",
    ]
    lines += [f"| {g} | {v:.3f} |" for g, v in r["explain"]["importance_group"].items()]
    lines += [
        "",
        "## Limitations",
        "- One static snapshot: no temporal validation is possible, and the drift section is a simulation.",
        "- Campaign economics are assumptions (see the sensitivity grid in the app).",
        "- The model predicts churn, not the causal effect of an offer.",
        "- SHAP explains the model, not the customer: it is not causal.",
        "",
        "## Promotion gate",
        "",
        "| Check | Result |",
        "|---|---|",
    ]
    lines += [f"| {c['check']} | {'pass' if c['passed'] else 'FAIL'} |" for c in r["gate"]["checks"]]
    return "\n".join(lines) + "\n"


def write_docs():
    _, report = registry.load()
    Path("docs").mkdir(exist_ok=True)
    Path("docs/model_card.md").write_text(model_card(report))


if __name__ == "__main__":
    write_docs()
